package io.knowledgebrain.integration;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.mock.web.MockHttpServletRequest;import jakarta.servlet.http.Cookie;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class GitHubApiTest {
 GitHubStore store;GitHubClient remote;SpaceAuthorizationClient auth;GitHubController api;UUID space,repo,actor;
 @BeforeEach void setup(){var ids=new UuidV7(Clock.systemUTC());space=ids.next();repo=ids.next();actor=ids.next();store=mock(GitHubStore.class);remote=mock(GitHubClient.class);auth=mock(SpaceAuthorizationClient.class);when(auth.authorize(eq(space),any(),anyBoolean(),anyString())).thenReturn(actor);api=new GitHubController(store,remote,auth,new SimpleMeterRegistry(),"https://localhost:8443");}
 MockHttpServletRequest req(String method,String body){var r=new MockHttpServletRequest(method,"/api/spaces/"+space+"/github/repositories/"+repo);r.setSecure(true);r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));r.addHeader("Origin","https://localhost:8443");r.addHeader("Idempotency-Key","b".repeat(32));r.setContentType("application/json");if(body!=null)r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 GitHubStore.Repository value(){return new GitHubStore.Repository(repo,space,"PRIVATE","42","octocat/Hello-World","https://github.com/octocat/Hello-World","main","ACTIVE",1,actor,"2026-11-01T00:00:00Z","2026-11-01T00:00:00Z",null);}
 @Test void eachReadChecksCurrentSpaceAndNeverCallsGithub(){when(store.get(space,repo)).thenReturn(value());for(int n=0;n<2;n++){var result=api.get(space.toString(),repo.toString(),req("GET",null));assertEquals("no-store",result.getHeaders().getCacheControl());assertEquals("\"ghr1\"",result.getHeaders().getETag());}verify(auth,times(2)).authorize(eq(space),eq("a".repeat(43)),eq(false),anyString());verifyNoInteractions(remote);reset(store);when(auth.authorize(eq(space),any(),anyBoolean(),anyString())).thenThrow(new ResponseStatusException(HttpStatus.NOT_FOUND));assertThrows(ResponseStatusException.class,()->api.get(space.toString(),repo.toString(),req("GET",null)));verifyNoInteractions(store);}
 @Test void creationChecksAuthorityBeforeAndAfterBoundedUpstreamAndReplayNeedsNoNetwork()throws Exception{var source=new GitHubClient.Repository("42","octocat/Hello-World",value().url(),"main");when(remote.repository("https://github.com/octocat/hello-world")).thenReturn(source);when(store.connect(eq(space),eq(actor),eq("b".repeat(32)),anyString(),eq(source),anyString())).thenReturn(new GitHubStore.Result(value(),false));var result=api.connect(space.toString(),req("POST","{\"url\":\"https://github.com/Octocat/Hello-World\"}"));assertEquals(201,result.getStatusCode().value());verify(auth,times(2)).authorize(eq(space),any(),eq(true),anyString());reset(remote);when(store.replay(space,actor,"b".repeat(32),"https://github.com/octocat/hello-world")).thenReturn(new GitHubStore.Result(value(),true));assertEquals(200,api.connect(space.toString(),req("POST","{\"url\":\"https://github.com/octocat/hello-world\"}")).getStatusCode().value());verifyNoInteractions(remote);}
 @Test void duplicateCredentialsOriginAndReadBodiesRejectBeforeDatabaseOrExternalCalls(){var insecure=req("GET",null);insecure.setSecure(false);assertThrows(ResponseStatusException.class,()->api.get(space.toString(),repo.toString(),insecure));var duplicate=req("GET",null);duplicate.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)),new Cookie("__Host-brain_guest","b".repeat(43)));assertThrows(ResponseStatusException.class,()->api.get(space.toString(),repo.toString(),duplicate));var origin=req("POST","{}");origin.removeHeader("Origin");assertThrows(ResponseStatusException.class,()->api.connect(space.toString(),origin));assertThrows(ResponseStatusException.class,()->api.list(space.toString(),req("GET","{}")));var q=req("GET",null);q.addParameter("actorId",actor.toString());assertThrows(ResponseStatusException.class,()->api.list(space.toString(),q));verifyNoInteractions(store,remote,auth);}
 @Test void malformedBodyUrlsDuplicateKeysAndStrongCasFailClosed()throws Exception{for(String body:List.of("{}","{\"url\":\"http://github.com/a/b\"}","{\"url\":\"https://github.com/a/b\",\"actorId\":\"spoof\"}","{\"url\":1}","{\"url\":\"https://github.com/a/b\",\"url\":\"https://github.com/a/c\"}","{} {}"))assertThrows(ResponseStatusException.class,()->api.connect(space.toString(),req("POST",body)));assertEquals(428,assertThrows(ResponseStatusException.class,()->api.sync(space.toString(),repo.toString(),req("POST","{}"))).getStatusCode().value());for(String tag:List.of("*","\"ghr0\"","\"ghr01\"","W/\"ghr1\"","\"tk1\"","\"ghr9223372036854775808\"")){var r=req("POST","{}");r.addHeader("If-Match",tag);assertThrows(ResponseStatusException.class,()->api.sync(space.toString(),repo.toString(),r));}verifyNoInteractions(store,remote);}
 @Test void syncReplayKeepsReceiptAndDoesNotRefetchOrReimport()throws Exception{var receipt=new GitHubStore.Receipt(new UuidV7(Clock.systemUTC()).next(),repo,1,"2026-11-01T00:00:00Z",0,0,null,false);when(store.syncReplay(space,repo,actor,"b".repeat(32),1)).thenReturn(new GitHubStore.Synced(value(),receipt,true));var r=req("POST","{}");r.addHeader("If-Match","\"ghr1\"");var response=api.sync(space.toString(),repo.toString(),r);assertTrue(response.getBody().replay());assertEquals(receipt,response.getBody().sync());verifyNoInteractions(remote);verify(store,never()).sync(any(),any(),any(),anyString(),anyLong(),any(),anyString());}
 @Test void upstreamFailureOrAuthorityLossAfterFetchCannotWriteCanonicalFacts()throws Exception{when(remote.repository(anyString())).thenThrow(GitHubClient.unavailable());assertThrows(ResponseStatusException.class,()->api.connect(space.toString(),req("POST","{\"url\":\"https://github.com/a/b\"}")));verify(store,never()).connect(any(),any(),anyString(),anyString(),any(),anyString());reset(auth,remote);when(auth.authorize(eq(space),any(),eq(true),anyString())).thenReturn(actor).thenThrow(new ResponseStatusException(HttpStatus.FORBIDDEN));when(remote.repository(anyString())).thenReturn(new GitHubClient.Repository("42","a/b","https://github.com/a/b","main"));assertThrows(ResponseStatusException.class,()->api.connect(space.toString(),req("POST","{\"url\":\"https://github.com/a/b\"}")));verify(store,never()).connect(any(),any(),anyString(),anyString(),any(),anyString());}
 @Test void errorsCarryNoStoreAndDoNotRevealUpstreamOrDatabaseDetails()throws Exception{var mvc=org.springframework.test.web.servlet.setup.MockMvcBuilders.standaloneSetup(api).setControllerAdvice(new GitHubErrors()).build();mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/spaces/"+space+"/github/repositories/"+repo+"/sync").secure(true).cookie(new Cookie("__Host-brain_guest","a".repeat(43))).header("Origin","https://localhost:8443").header("Idempotency-Key","b".repeat(32)).contentType("application/json").content("{}")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().is(428)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.header().string("Cache-Control","no-store"));}
}
